INSERT INTO "convergence_assessment" ("convergence_id", "status", "clinical_sources", "co1_sources", "co2_sources", "down_weighted_sources", "discounted_sources", "rationale", "synthesis_approach", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (6, 'pending_assessment', '["REF-00983", "REF-00985", "REF-00986", "REF-00984"]', '["REF-00989", "REF-00993"]', '[]', '[]', '["REF-00987", "REF-00988", "REF-00990", "REF-00991", "REF-00992", "REF-00994", "REF-00995", "REF-00997"]', 'PROXY: the regulatory stratum supplies the threshold (>=1 T4 international standard present (§2.3; the clause''s ''value directly addressing the parameter'' is unverified — value extraction pending)) and 6 anchoring-tier finding(s) supply the direction. The value is selected most-accommodatingly within what the threshold permits; no source states it. Owner 2026-09-16: ''yes it''s not perfect it''s a proxy''.', NULL, '2026-09-18 01:40:00', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', NULL, NULL);
INSERT INTO "evidence_sources" ("ref_id", "source_type", "author_count", "author_count_is_complete", "first_author_last", "first_author_first", "is_corporate_primary", "author_display", "pub_year", "pub_year_note", "pub_title", "pub_subtitle", "chapter_title", "original_title", "lang_detected", "lang_detection_method", "pub_title_en", "pub_subtitle_en", "chapter_title_en", "journal_name_en", "translation_method", "translation_reviewed", "journal_name", "journal_abbrev", "volume", "issue", "pages_start", "pages_end", "article_number", "publisher", "publisher_location", "edition", "book_title", "series", "series_number", "report_number", "institution", "standard_number", "doi", "pmid", "pmcid", "isbn", "issn", "url", "url_accessed", "handle", "local_id", "tier", "evidence_type", "jurisdiction", "co1_provenance", "co1_source_type", "synthesis_attribution_required", "metadata_quality", "verification_status", "doi_resolution_outcome", "bpc_shorthand", "bpc_note", "grey_flag", "grey_reason", "verification_note", "prior_expectation", "search_queries_used", "derivation_chain", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "verified_by_tool", "last_verified_at", "verification_attempt_count", "superseded_by_ref_id", "pages", "pub_month", "language", "subtype", "citation_count", "url_resolution_outcome", "url_last_fetched", "url_match_similarity", "metadata_integrity_status", "metadata_integrity_detail", "code_currency_status", "code_currency_verified_at", "code_currency_verified_by_session", "code_currency_notes", "scope", "data_capture_status", "citation_mining_status", "processing_blocked_reason", "standard_number_note", "author_display_note", "publisher_note", "verification_disposition", "verification_method", "verification_closure_reason") VALUES ('REF-00997', NULL, NULL, 0, NULL, NULL, 0, NULL, 2013, NULL, 'Equipment Program Clinical Considerations for Prescribers — Home Modifications: Ramps', NULL, NULL, NULL, 'EN', 'document body is English throughout', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://des.sa.gov.au/__data/assets/word_doc/0011/21044/ramps-clinical-considerations-for-prescribers.doc', '2026-09-18', NULL, NULL, 5, 'national_fw', 'AU', NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'NO-MATCH', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', 'retrieval_log.fetch', NULL, 1, NULL, '3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'intrinsic', 'captured', 'pending', NULL, NULL, NULL, NULL, 'CLOSED', 'direct-render', NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-007', 'SW', 'P2', 'OPEN', NULL, NULL, 'relate-extraction HAS NO --verbatim-exempt AND add-extraction DOES, SO A CONDITION READ FROM A NON-UTF-8 PAYLOAD CANNOT BE GIVEN THE EDGE A BLOCKING CHECK DEMANDS. Measured in batch 13 on REF-00997, a legacy OLE .doc encoded CP1252. add-extraction accepted the rows under --verbatim-exempt, which exists precisely for an artefact the checker cannot decode. relate-extraction then refused the condition_on edge because --quote is required and the quote byte-check reports the same artefact NOT SEARCHED. extraction_relations_integrity (BLOCKING) in turn fails any figure_role=condition that qualifies nothing. The three rules are individually right and jointly make one state unreachable: a proviso extracted from a PDF, a .doc or any non-UTF-8 payload can be written but never correctly related. Batch 13 was not blocked by this -- the precedent-correct role for its row turned out to be finding (REF-00992 ext 26, REF-00994 ext 29) rather than condition -- so this is recorded as a latent trap, not a live one. The next genuine proviso in a PDF hits it. Fix shape: give relate-extraction the same --verbatim-exempt add-extraction already has, ledgered on the edge the way it is ledgered on the row.', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (54, 'accessible-circulation-geometry', 'GB', 'EN', 2, 'co2', 'national', 'Royal College of Occupational Therapists housing adaptations guidance ramp gradient slope wheelchair', NULL, 'web', 'scoping', NULL, 10, 10, 0, 'saturated', NULL, NULL, 0, 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48', 'ZERO, AND IT REPRODUCES A RESULT ALREADY IN THE DB. Batch 09 read Adaptations without Delay in full and found no gradient anywhere; this pass surfaced the same ecosystem (RCOT, Housing LIN, The OT Practice) and no RCOT-authored gradient. R14 shape: well-formed query, correct index, GENUINE ABSENCE. Its value is the delegation chain it surfaced -- RCOT delegates ramp design to Foundations, and Foundations (see the GB national_fw search in this batch) delegates to Approved Document M. The chain from the OT professional body to a gradient terminates at the building regulator with no OT-discipline warrant at any link.', 0, 'PRIORS.md (committed 3db5769, before any query): OT professional guidance is about the assessment, not the dimension; expect no gradient from the UK professional body.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (55, 'accessible-circulation-geometry', 'US', 'EN', 2, 'co2', 'national', 'AOTA occupational therapy practice guidelines home modifications ramp slope recommendation', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'partial', NULL, NULL, 0, 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48', 'ZERO ADMITTED; candidate 73 UNCHANGED and still an R14 RETRIEVAL FAILURE (library.aota.org member-gated). PRIOR SUPPORTED BUT NOT FROM THE SOURCE: third parties describe the AOTA guideline as addressing "ramp slope specifications according to ADA vs state codes", and one page asserts 1:12 "according to occupational therapy home modification standards". BOTH ARE THIRD-PARTY CHARACTERISATIONS, NOT THE CPG, and nothing was admitted or re-described from them (R15, CLAUDE.md 5(c)). Ladder rungs still untried: WorldCat, Google Books preview, archived NGC summary (ISBN 9781569003572).', 0, 'PRIORS.md (committed 3db5769, before any query): where an OT CPG does state a gradient, expect it to RESTATE A NATIONAL CODE rather than carry its own warrant.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (56, 'accessible-circulation-geometry', 'GB', 'EN', 5, 'national_fw', 'national', 'Foundations "Guidance for Ramp Adaptations" home improvement agencies England ramp gradient 1:15 1:12 PDF', NULL, 'web', 'systematic', NULL, 9, 9, 0, 'saturated', NULL, NULL, 0, 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48', 'THE SNIPPET WAS WRONG AND THE RETRIEVAL PROVED IT. The search index attributes to this page "ramps up to 10m: 1 in 15; up to 5m: 1 in 12". Retrieved (live URL 403 Cloudflare; R10 ladder to Wayback, 200, 69711 bytes, sha256 b201d3be..., snapshot 2023-12-07): the page contains ZERO instances of 1:15, 1:12, 10m or 5m. It states 1:20 as the walkway/ramp BOUNDARY ("For a walkway to be considered accessible, the gradient (slope) must not be steeper than 1:20. A gradient steeper than 1:20 would be considered a ramp") and 1:40 crossfall, then DELEGATES ramp design to Charnwood Borough Council guidance and Approved Document M. Batch 09 candidate 72 called this page "the apparent source of the 1:15/1:12 length-conditioned figures" -- FALSIFIED, and the candidate is re-described per R15. NOT ADMITTED for parameter 3: its 1:20 is a definitional boundary for walkways, not a ceiling on ramps, and filing it as a ramp maximum is the copy rule 5 forbids. CAVEAT: this holds for the 2023-12-07 snapshot; the live page is blocked and unverified.', 0, 'PRIORS.md (committed 3db5769, before any query) target 1: expect rise/length-conditioned gradients, and expect T5 national_fw rather than Co-2 because Foundations is the national body for home improvement agencies, not an OT professional body.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (57, 'accessible-circulation-geometry', 'AU', 'EN', 2, 'co2', 'national', 'Australian Home Modification Guidelines occupational therapy evidence-based ramp gradient wheelchair slope recommendation', NULL, 'web', 'scoping', NULL, 10, 10, 1, 'partial', NULL, NULL, 0, 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48', 'ONE ADMISSION, AND IT IS NOT Co-2. SWEP (Victoria) Practitioner Manual: DEAD LINK -- HTTP 200 with a 20-byte body reading "File does not exist."; staged as a candidate. SA Equipment Program "Ramps - Clinical Considerations for Prescribers": live URL 403 Cloudflare, R10 ladder to Wayback 200, 159744 bytes application/msword, sha256 1d4ebe3dd57422e2. States a rise-conditioned pair (1:8 step ramps rise <190mm; 1:14 long ramps rise >190mm) AND an individualisation duty: "Assess the client s/carer s ability to propel the wheelchair over this gradient as some clients may require a less steep gradient." Admitted REF-00997 at T5 national_fw, NOT Co-2: a state government equipment program is not an OT professional body, and the document grounds itself in AS 1428.1 -- the 2026-09-13 ruling puts value-restating material in the regulatory stratum. STILL ZERO Co-2 IN THE CORPUS, now for a third recorded reason.', 0, 'PRIORS.md (committed 3db5769, before any query) target 4: bodies never searched (CAOT, OT Australia, WFOT) are where a genuine Co-2 admission could still come from; R5 applies.');
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-18-resea-REF-00997-MOB', 'REF-00997', 'MOB', 'No study population — a state equipment programme stating prescription guidance for clinicians; no participants, no measurement, no citation', NULL, 'PROXY', 'PROXY on the same ground as REF-00987/94/95/96: an institution stating what wheelchair users need, with nobody in the room. Worth naming precisely because this document comes closest in the corpus to speaking for an individual disabled person -- it instructs the prescriber to assess THIS client and permits a gentler gradient for them. That is an individualisation DUTY, not evidence about a population, and it does not raise the grade. The document tells a clinician to go and find out; it does not report having found out.', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', 'REF-00997', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (139, 'REF-00997', 1, NULL, NULL, NULL, NULL, 1, 'DCSI Equipment Program', NULL, 'author', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', NULL);
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (24, 'REF-00997', 'step ramp', 'EN', 'Ramp gradient', 'For step ramps with rise <190mm, the recommended gradient is 1:8.', 'A DEVICE CLASS USED AS A GRADIENT BAND. The document splits its recommendation on "step ramp" vs "long ramp" at a 190mm rise, so the phrase does real work: it names the object whose permitted gradient is 1:8 rather than 1:14. Whether it names one of our concepts is for judgment (D-0173); recorded verbatim and unjudged.', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (25, 'REF-00997', 'long ramp', 'EN', 'Ramp gradient', 'For long ramps with rise >190mm, the recommended gradient is 1:14.', 'The complement of "step ramp" in the same sentence pair, and the carrier of this document governing figure. Recorded verbatim and unjudged (D-0173).', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (26, 'REF-00997', 'prescriber', 'EN', 'Australian Standards; Ramp gradient', 'the clinical reasoning for this should be thoroughly documented by the prescriber', 'THE ACTOR THE WHOLE DOCUMENT ADDRESSES, and the reason this source is interesting to the Co-2 question even though it is not Co-2. "Prescriber" is a clinical role and the document assigns the gradient decision to it -- including authority to depart from AS 1428.1 on documented clinical reasoning. No other source in this corpus names a person who decides. Unjudged (D-0173).', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (57, 'REF-00997', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (84, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'SWEP (Statewide Equipment Program, Victoria), "Practitioner Manual for Home Modifications" — the Victorian counterpart to the South Australian prescriber guidance admitted as REF-00997. HYPOTHESIS PER R15: expect prescriber-facing home-modification guidance stating a ramp gradient grounded in AS 1428.1, i.e. a second state-level instance of the same shape, not a Co-2 source. UNVERIFIED — not read.', 'https://swep.bhs.org.au/files/320/SWEP_Home_Modifications_Prescriber_Manual.pdf', 'DEAD', 5, 0, 'DEAD LINK, AND THE FAILURE MODE IS WORTH RECORDING: the URL returns HTTP 200 with a 20-byte body reading "File does not exist." A status-code-only check would score this as a successful retrieval. retrieval_log persisted it (sha256 f056e72fad232b2e), so the artefact shows what actually arrived. R14: a RETRIEVAL failure, not evidence of absence.', NULL, 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (85, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'AOTA, "Occupational Therapy Practice Guidelines for Home Modifications" (Siebert, Smallfield, Stark) — LADDER RUNGS FOR CANDIDATE 73, which batch 09 left at member-gated. This is a BOOK, ISBN 9781569003572, so the untried rungs are WorldCat, a Google Books preview, and the archived National Guideline Clearinghouse summary. R15 HYPOTHESIS, UNREAD: third-party descriptions say it addresses "ramp slope specifications according to ADA vs state codes", which if true makes it code-restating and therefore regulatory-stratum under the 2026-09-13 ruling rather than an anchoring Co-2 CPG. THAT IS A HYPOTHESIS ABOUT A DOCUMENT NOBODY IN THIS PROJECT HAS READ.', 'ISBN 9781569003572', 'UNVERIFIED', 2, 0, 'Still not retrieved. Batch 09 recorded the library.aota.org block and stopped; R10 says a publisher block is not a terminal answer, and three rungs remain untried. Recorded as distinct from candidate 73 because it names the rungs rather than repeating the block.', NULL, 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-00997', 'accessible-circulation-geometry', '16', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (33, 'REF-00997', 'accessible-circulation-geometry', 3, 'MOB', NULL, 'A-EFFORT', NULL, 'AU', 'home environment (domiciliary equipment prescription)', 'qualitative', 'the prescriber must assess whether this client can propel over the recommended gradient; some require gentler', NULL, 'Assess the client’s/carer’s ability to propel the wheelchair over this gradient as some clients may require a less steep gradient.', 'Ramp gradient', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'THE SECOND CRITERION-OF-ACCEPTABILITY STATEMENT IN THE CORPUS, AND THE FIRST PLACING THE DUTY ON A NAMED CLINICIAN. REF-00996 (Flemish handbook) states the criterion as a design principle -- physical feasibility for the independently self-propelling wheelchair user is the starting point. This states it as an OPERATIONAL DUTY: the tabulated gradient is a default and the prescriber must test it against this client. It names no number, so it is a finding and reaches a determination only through the proxy branch (086). SECOND LENS DELIBERATE: A-EFFORT ("cost little energy... rest points", absorbing fatigue, pain, cardiac/respiratory) is what an ability-to-propel assessment is about, and every other parameter-3 extraction carries identity_code MOB and nothing else. R4 asks for the combinatorial dimension; this is one honest step, not a backfill of the other 22 rows. VERBATIM NOTE: claim_text carries U+2019 apostrophes as the CP1252 bytes do; an ASCII-stripped reading rendered them as spaces and was discarded as a decode artefact, not a quotation. [VERBATIM-EXEMPT: ARTEFACT IS PERSISTED BUT NOT UTF-8 DECODABLE. Payload: retrieval-log/session_2026-09-18-research-batch-13-co2-occupational-therapy/1d4ebe3dd57422e2.doc, 159744 bytes, application/msword, HTTP 200 via the R10 Wayback ladder after the live URL returned 403. Legacy OLE compound document encoded CP1252, so the verbatim checker classifies it NOT SEARCHED (not valid UTF-8, no charset declaration) and cannot see text that IS present in the bytes. Re-derivable in one line: open(path,"rb").read().decode("cp1252") then search for the sentence. NOT exempt because the text was unretrievable -- exempt because the checker cannot read a format it was handed. A UTF-8 rendition was deliberately NOT generated to satisfy the gate: an artefact this session wrote itself would make the check circular.]', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (34, 'REF-00997', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'AU', 'home environment (domiciliary equipment prescription)', 'numerical', '1:14', 'rise:run ratio', 'For long ramps with rise >190mm, the recommended gradient is 1:14.', 'Ramp gradient', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'COMPARATOR IS <=, NOT A POINT, AND THE SOURCE WARRANTS IT. The sentence carries no comparator of its own; read as a POINT it would contribute a floor as well as a ceiling and produce exactly the incoherent interval assess_cell now refuses (the REF-00987 defect). Two sentences in the same document make <= honest: ''some clients may require a less steep gradient'' (gentler is expressly in scope) and ''wherever possible, any ramp complies with AS 1428.1'' (the figure is a compliance ceiling). CONTEXT, RECORDED HERE BECAUSE IT IS NOT AN EDGE. The document opens "Refer to the Australian Standard for Design for Access and Mobility (AS 1428.1) section on walkways, ramps and landings" and says "wherever possible, any ramp complies with AS 1428.1", adding that where space or a client disability-related need prevents compliance "the clinical reasoning for this should be thoroughly documented by the prescriber". That is FRAMING, not a comparator edge: the writer refuses audited_against on a figure_role=claim precisely because auditing against a baseline asserts no absolute value of its own, and this document does state its figure. AS 1428.1 is not a row this project holds, so no derived_from edge can be written either. No derivation is asserted: the document never says these figures are lifted from the standard. [VERBATIM-EXEMPT: ARTEFACT IS PERSISTED BUT NOT UTF-8 DECODABLE. Payload: retrieval-log/session_2026-09-18-research-batch-13-co2-occupational-therapy/1d4ebe3dd57422e2.doc, 159744 bytes, application/msword, HTTP 200 via the R10 Wayback ladder after the live URL returned 403. Legacy OLE compound document encoded CP1252, so the verbatim checker classifies it NOT SEARCHED (not valid UTF-8, no charset declaration) and cannot see text that IS present in the bytes. Re-derivable in one line: open(path,"rb").read().decode("cp1252") then search for the sentence. NOT exempt because the text was unretrievable -- exempt because the checker cannot read a format it was handed. A UTF-8 rendition was deliberately NOT generated to satisfy the gate: an artefact this session wrote itself would make the check circular.]', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (35, 'REF-00997', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'AU', 'home environment (domiciliary equipment prescription)', 'numerical', '1:8', 'rise:run ratio', 'For step ramps with rise <190mm, the recommended gradient is 1:8.', 'Ramp gradient', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'FIGURE_ROLE IS finding, FOLLOWING REF-00992 EXTRACTION 26 AND REF-00994 EXTRACTION 29 -- NOT condition. The first pass filed this as a condition by analogy to REF-00990 extraction 23, the Japanese 8-fold proviso, and that analogy was wrong twice over. Substantively: 00990''s row is a ただし書 proviso EXCEPTING a stated ceiling, whereas these two sentences are PARALLEL BRANCHES of one rule split at a rise threshold, which is the shape Approved Document M''s gradient table and the IPC''s two grades already have -- and both of those are filed finding, with no edges. Procedurally: extraction_relations_integrity requires a condition to qualify a row, relate-extraction requires a --quote, and the quote byte-check cannot read this CP1252 artefact, so a condition here was unwritable-with-edge and failed the blocking check. The precedent and the toolchain point the same way, and the precedent is the reason -- see the gap registered by this session for the toolchain half. A small-rise exception is not the parameter general rule, and admitting it as a claim would put a 12.5 percent ceiling into the governing set on a parameter whose current selection is 5 percent. A coincidence worth not over-reading: JP and AU both land on 1:8 for the small-rise case, at different thresholds (160mm vs 190mm), from unrelated instruments. CONTEXT, RECORDED HERE BECAUSE IT IS NOT AN EDGE. The document opens "Refer to the Australian Standard for Design for Access and Mobility (AS 1428.1) section on walkways, ramps and landings" and says "wherever possible, any ramp complies with AS 1428.1", adding that where space or a client disability-related need prevents compliance "the clinical reasoning for this should be thoroughly documented by the prescriber". That is FRAMING, not a comparator edge: the writer refuses audited_against on a figure_role=claim precisely because auditing against a baseline asserts no absolute value of its own, and this document does state its figure. AS 1428.1 is not a row this project holds, so no derived_from edge can be written either. No derivation is asserted: the document never says these figures are lifted from the standard. [VERBATIM-EXEMPT: ARTEFACT IS PERSISTED BUT NOT UTF-8 DECODABLE. Payload: retrieval-log/session_2026-09-18-research-batch-13-co2-occupational-therapy/1d4ebe3dd57422e2.doc, 159744 bytes, application/msword, HTTP 200 via the R10 Wayback ladder after the live URL returned 403. Legacy OLE compound document encoded CP1252, so the verbatim checker classifies it NOT SEARCHED (not valid UTF-8, no charset declaration) and cannot see text that IS present in the bytes. Re-derivable in one line: open(path,"rb").read().decode("cp1252") then search for the sentence. NOT exempt because the text was unretrievable -- exempt because the checker cannot read a format it was handed. A UTF-8 rendition was deliberately NOT generated to satisfy the gate: an artefact this session wrote itself would make the check circular.]', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:48', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', 'finding', '<=');
INSERT INTO "specifications" ("specification_id", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "state", "design_scale", "convergence_id", "confidence_dimensions_present", "confidence_dimensions_absent", "confidence_synthesis_basis", "gap_register_id", "not_applicable_rationale", "tier_basis", "governing_refs", "rule_version", "derivation_sha", "code_floor_only", "value_min", "value_max", "value_unit", "falsification_condition", "has_unverified_sources", "all_sources_disqualified", "regulatory_stratum_only", "created_at", "created_by_session", "updated_at", "updated_by_session", "value_note", "functional_basis", "derivation_rationale", "cultural_claim_anchor", "derivation_paths", "retired_at", "retired_by_session", "retirement_reason", "superseded_by_specification_id", "rests_on_proxy_inference", "value_notations") VALUES (6, 3, 'MOB', NULL, NULL, NULL, 'provisional', 'universal', 6, '["Tier 4-5 standards (3)", "Tier 6 statutory codes (5)", "Anchoring-tier findings supplying direction (6: T1+CO1+T2)"]', '["No source states a value for this parameter at an anchoring tier -- the threshold is regulatory and the direction is inferred, so this is a PROXY determination and not a best-practice claim"]', 'Threshold from the regulatory stratum (>=1 T4 international standard present (§2.3; the clause''s ''value directly addressing the parameter'' is unverified — value extraction pending)), direction from measured findings. A proxy inference under the owner statement of 2026-09-16, marked as one.', NULL, NULL, 'T4-6-only-threshold+T1+CO1+T2-direction(proxy_inference)', '["REF-00987", "REF-00988", "REF-00990", "REF-00991", "REF-00992", "REF-00994", "REF-00995", "REF-00997"]', 'pilot-3', '83b6b8e60365039028ff46aea9d91e96f28d1c9c311ba7ce2b6dca44a34c5ac2', 0, NULL, 5.0, '%', 'Overturned if a source states a value for this parameter at an anchoring tier (the cell then rests on that, not on a proxy), if the findings supplying direction are retracted or re-graded off `finding`, or if the cited threshold editions are superseded. It does NOT become a best-practice claim by more codes agreeing (§2.7), and the proxy step is degenerate without the threshold: ''best outcomes'' alone resolves to the gentlest gradient physically possible, which for a ramp is not a ramp.', 0, 0, 0, '2026-09-18 01:40:00', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', '2026-09-18 01:40:00', 'session_2026-09-18-research-batch-13-co2-occupational-therapy', 'value presented in 2 notations of one quantity (owner ruling 2026-09-17: present both, never choose)', '[{"icf_code": "d410", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d420", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d450", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d455", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d460", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d465", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d470", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d510", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "